#include <Arduino.h>

void setup() {
  pinMode(8, OUTPUT);
  pinMode(9, INPUT);
  pinMode(2, OUTPUT);
  pinMode(3, OUTPUT);
  pinMode(4, OUTPUT);
  digitalWrite(8, LOW);
  digitalWrite(2, LOW);
  digitalWrite(3, LOW);
  digitalWrite(4, LOW);
}

void loop() {
  digitalWrite(8, LOW);
  delayMicroseconds(2);
  digitalWrite(8, HIGH);
  delayMicroseconds(10);
  digitalWrite(8, LOW);
  unsigned long duration = pulseIn(9, HIGH, 30000UL);
  if (duration != 0) {
    float distance = duration / 58.0f;
    bool occupied = distance < 50.0f;
    digitalWrite(4, occupied ? HIGH : LOW);
    digitalWrite(3, occupied ? LOW : HIGH);
    digitalWrite(2, LOW);
  }
  delay(60);
}
